contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address other) public {
        // Precondition: the caller (this contract) starts with no balance so airDrop is allowed.
        require(c.tokenBalance(address(this)) == 0);
        require(other != address(this));

        // Snapshot the other account's balance before the deciding call.
        uint beforeOther = c.tokenBalance(other);

        // Deciding call: airDrop must succeed for a fresh caller.
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After a successful airDrop, the caller's balance is exactly 20 and no other balance decreased.
        assert(
            reverted ||
            (c.tokenBalance(address(this)) == 20 && c.tokenBalance(other) == beforeOther)
        );
    }
}

