contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address who) public {
        uint before = c.tokenBalance(who);

        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after_ = c.tokenBalance(who);

        if (!reverted && who == address(this)) {
            assert(after_ == 20);
        } else if (reverted) {
            assert(after_ == before);
        } else {
            assert(after_ >= before);
        }
    }
}

